15	/**
16	 * Issues an HTTP GET and resolves with the parsed response. The returned
17	 * `req` allows tests to abort the request before it completes.
18	 */
19	export function rawGet(
20	  port: number,
21	  path: string,
22	  options: { headers?: Record<string, string> } = {},
23	): Promise<RawRequestResult> & { req?: http.ClientRequest } {
24	  let req: http.ClientRequest;
25	  const promise = new Promise<RawRequestResult>((resolve, reject) => {
26	    req = http.get(
27	      {
28	        port,
29	        path,
30	        headers: { Connection: 'close', ...options.headers },
31	      },
32	      res => {
33	        let rawBody = '';
34	        res.setEncoding('utf8');
35	        res.on('data', chunk => (rawBody += chunk));
36	        res.on('end', () => {
37	          let body: any = rawBody;
38	          try {
39	            body = rawBody ? JSON.parse(rawBody) : null;
40	          } catch {
41	            // leave body as the raw string
42	          }
43	          resolve({ statusCode: res.statusCode ?? 0, body, rawBody, req });
44	        });
45	      },
46	    );
47	    req.on('error', error => {
48	      const typed = error as NodeJS.ErrnoException;
49	      if (typed.code === 'ECONNRESET' || typed.code === 'EPIPE') {
50	        resolve({
51	          statusCode: 0,
52	          body: null,
53	          rawBody: '',
54	          req,
55	        });
56	        return;
57	      }
58	      reject(error);
59	    });
60	  }) as Promise<RawRequestResult> & { req?: http.ClientRequest };
61	  promise.req = req!;
62	  return promise;
63	}
