68	export async function waitForRecords(
69	  port: number,
70	  predicate: (records: any[]) => boolean,
71	  timeoutMs = 3000,
72	): Promise<any[]> {
73	  const deadline = Date.now() + timeoutMs;
74	  let records: any[] = [];
75	  while (Date.now() < deadline) {
76	    const result = await rawGet(port, '/context-records');
77	    records = result.body?.records ?? [];
78	    if (predicate(records)) {
79	      return records;
80	    }
81	    await new Promise(resolve => setTimeout(resolve, 20));
82	  }
83	  throw new Error(
84	    `waitForRecords timed out; last records: ${JSON.stringify(records)}`,
85	  );
86	}
