633	 *
634	 * - `GET /context-probe?marker=...` stores the marker in the request
635	 *   snapshot, registers one or more post-response callbacks (each parked
636	 *   behind a per-registration gate until tests release it) and completes the
637	 *   response.
638	 * - `GET /context-records` reads back every registration with its current
639	 *   lifecycle state.
640	 * - `GET /release-gates[?callbackId=...]` releases pending callback gates.
641	 */
642	@Controller()
643	export class AppController {
644	  constructor(private readonly records: ContextRecordsStore) {}
645	
646	  @Get('context-probe')
647	  public async probe(
648	    @Query('marker') marker: string | undefined,
649	    @Query('consumerValue') consumerValue: string | undefined,
650	    @Query('delayMs') delayMs: string | undefined,
651	    @Query('fail') fail: string | undefined,
652	    @Query('registrations') registrations: string | undefined,
653	    @Query('failCallbackIndex') failCallbackIndex: string | undefined,
654	    @RequestContext() context: RequestContextSnapshot | undefined,
655	    @Req() request: any,
656	  ): Promise<{
657	    contextId: string;
658	    callbackIds: string[];
659	    aborted?: boolean;
660	  }> {
661	    if (!context) {
662	      throw new Error('Request context snapshot was not attached');
663	    }
664	    if (typeof marker !== 'string' || marker.length === 0) {
665	      throw new BadRequestException('marker query parameter is required');
666	    }
667	
668	    // Metadata extracted at the beginning of the request.
669	    context.set('marker', marker);
670	
671	    const count = clampRegistrations(registrations);
672	    const callbackIds: string[] = [];
673	    const failingIndex = parseOptionalIndex(failCallbackIndex);
674	
675	    for (let i = 0; i < count; i++) {
676	      const registrationIndex = i;
677	      const callbackId = context.registerAfterTerminated(
678	        async (snapshot: RequestContextSnapshot) => {
679	          try {
680	            // The callback body stays parked until the test releases the
681	            // gate (or shutdown releases every gate). Meanwhile the record
682	            // already reports "frozen", so the probe can distinguish
683	            // "terminated, callback waiting" from "callback completed".
684	            await this.records.waitForGate(callbackId);
685	
686	            if (fail === 'callback' || failingIndex === registrationIndex) {
687	              throw new Error(`intentional callback failure: ${marker}`);
688	            }
689	
690	            const firstRead = snapshot.get<string>('marker') ?? null;
691	            await Promise.resolve();
692	            const secondRead = snapshot.get<string>('marker') ?? null;
693	
694	            const lateWriteAccepted = snapshot.set('lateWrite', marker);
695	            const lateWriteVisible = snapshot.has('lateWrite');
696	            const thirdRead = snapshot.get<string>('marker') ?? null;
697	
698	            this.records.markCompleted(callbackId, {
699	              terminationReason: snapshot.getTerminationReason(),
700	              terminationCount: snapshot.getTerminationCount(),
701	              consumerValue: snapshot.get<string>('consumerValue') ?? null,
702	              frozenMarker: firstRead,
703	              lateWriteAccepted,
704	              lateWriteVisible,
705	              repeatedReadsConsistent:
706	                firstRead === marker &&
707	                secondRead === marker &&
708	                thirdRead === marker,
709	            });
710	          } catch (error) {
711	            // A failing callback only fails its own record; other callbacks
712	            // and other requests are untouched.
713	            this.records.markFailed(callbackId, error);
714	          }
715	        },
716	      );
717	
718	      // Every registration is an independent record, even for repeated or
719	      // identical markers.
720	      this.records.register(context.id, callbackId, marker);
721	      // Freeze observer (a microtask once terminate resolves waiters) runs
722	      // before the callback, which is scheduled with setImmediate.
723	      void context.whenFrozen().then(() => {
724	        this.records.markFrozen(callbackId, context);
725	      });
726	      callbackIds.push(callbackId);
727	    }
728	
729	    // A different consumer of the same request writes after the callbacks
730	    // were registered but still before termination: callbacks must observe
731	    // this value, registration order notwithstanding.
732	    if (consumerValue !== undefined) {
733	      context.set('consumerValue', consumerValue);
734	    }
735	
736	    if (fail === 'request') {
737	      throw new BadRequestException('intentional controller failure');
738	    }
739	
740	    if (fail === 'filtered') {
741	      throw new FilteredProbeError(marker);
742	    }
743	
744	    if (delayMs !== undefined) {
745	      const aborted = await waitForCompletionOrAbort(
746	        request,
747	        Number.parseInt(delayMs, 10) || 0,
748	      );
749	      if (aborted) {
750	        // The client went away; the raw response 'close' listener owned by
751	        // RequestContextHost has already terminated the snapshot as 'abort'.
752	        return { contextId: context.id, callbackIds, aborted: true };
753	      }
754	    }
755	
756	    return { contextId: context.id, callbackIds };
757	  }
