780	function clampRegistrations(registrations: string | undefined): number {
781	  const parsed = Number.parseInt(registrations ?? '1', 10);
782	  if (!Number.isFinite(parsed) || parsed < 1) {
783	    return 1;
784	  }
785	  return Math.min(parsed, 10);
786	}
