796	/**
797	 * Resolves `true` when the underlying request socket closes before `ms`
798	 * elapses (client aborted), `false` on a normal timeout. Works with the
799	 * Express request (an `IncomingMessage`) and the Fastify request wrapper
800	 * (which exposes the raw message as `raw`).
801	 */
802	function waitForCompletionOrAbort(request: any, ms: number): Promise<boolean> {
803	  const rawRequest = request?.raw ?? request;
804	  return new Promise<boolean>(resolve => {
805	    let settled = false;
806	    const onClose = () => {
807	      if (settled) {
808	        return;
809	      }
810	      settled = true;
811	      clearTimeout(timer);
812	      resolve(true);
813	    };
814	    const timer = setTimeout(() => {
815	      if (settled) {
816	        return;
817	      }
818	      settled = true;
819	      rawRequest.removeListener?.('close', onClose);
820	      resolve(false);
821	    }, ms);
822	    rawRequest.once?.('close', onClose);
823	  });
824	}
