15	async function getFreePort(): Promise<number> {
16	  return new Promise((resolve, reject) => {
17	    const server = http.createServer();
18	    server.unref();
19	    server.on('error', reject);
20	    server.listen(0, () => {
21	      const { port } = server.address() as { port: number };
22	      server.close(() => resolve(port));
23	    });
24	  });
25	}
26	
27	async function expectPortClosed(port: number): Promise<void> {
28	  await expect(
29	    new Promise((resolve, reject) =>
30	      http
31	        .get({ port, path: '/health', timeout: 1000 }, resolve)
32	        .on('error', reject),
33	    ),
34	  ).rejects.toMatchObject({ code: 'ECONNREFUSED' });
35	}
36	
37	/**
38	 * Failure-mode guarantees:
39	 * - failed initialization never yields a servable half-initialized app;
40	 * - records completed before a later failure are never rewritten;
41	 * - concurrently running applications never expose each other's data.
42	 */
43	export function registerLifecycleSuite(platform: HttpPlatform): void {
44	  describe(`Lifecycle and isolation guarantees (${platform})`, () => {
45	    let app: INestApplication;
46	    let port: number;
47	
48	    afterEach(async () => {
49	      await app?.close();
50	    });
51	
52	    it('rejects construction-phase failures without binding any server', async () => {
53	      await expect(
54	        createApp(FailingConstructorModule, platform, {
55	          abortOnError: false,
56	        }),
57	      ).rejects.toThrow('intentional constructor failure');
58	
59	      // create() threw before returning an application, so there is no app to
60	      // close and no listener could have been installed.
61	      const freePort = await getFreePort();
62	      await expectPortClosed(freePort);
63	    });
64	
65	    it('rejects onModuleInit failures without serving traffic', async () => {
66	      // create() succeeds (the container is built) but listen() runs init()
67	      // hooks and must reject; the server must never accept a request.
68	      app = await createApp(FailingInitModule, platform, {
69	        abortOnError: false,
70	      });
71	      const fixedPort = await getFreePort();
72	
73	      await expect(app.listen(fixedPort)).rejects.toThrow(
74	        'intentional initialization failure',
75	      );
76	      await expectPortClosed(fixedPort);
77	
78	      // The failed application must still be closable without hanging.
79	      await app.close();
80	      await expectPortClosed(fixedPort);
81	    }, 10_000);
82	
83	    it('does not rewrite completed records when a later request fails', async () => {
84	      app = await createApp(AppModule, platform);
85	      port = await getPort(app);
86	
87	      const good = await rawGet(port, '/async-context?marker=keep');
88	      await rawGet(port, '/release-gates');
89	      const settled = await waitForRecords(
90	        port,
91	        items =>
92	          recordById(items, good.body.recordIds[0]).status === 'completed',
93	      );
94	      const completedId = good.body.recordIds[0];
95	      const completedRecord = JSON.stringify(recordById(settled, completedId));
96	
97	      const broken = await rawGet(
98	        port,
99	        '/async-context?marker=broken&fail=request',
100	      );
101	      expect(broken.statusCode).toBe(400);
102	
103	      const after = await rawGet(port, '/async-records');
104	      expect(JSON.stringify(recordById(after.body.records, completedId))).toBe(
105	        completedRecord,
106	      );
107	    });
108	
109	    it('keeps records isolated between two concurrently running applications', async () => {
110	      app = await createApp(AppModule, platform);
111	      port = await getPort(app);
112	      const otherApp = await createApp(AppModule, platform);
113	      const otherPort = await getPort(otherApp);
114	      try {
115	        const a = await rawGet(port, '/async-context?marker=app-a');
116	        const b = await rawGet(otherPort, '/async-context?marker=app-b');
117	        expect(a.body.appId).not.toBe(b.body.appId);
118	
119	        await rawGet(port, '/release-gates');
120	        await rawGet(otherPort, '/release-gates');
121	
122	        const [recordsA, recordsB] = await Promise.all([
123	          waitForRecords(port, items =>
