1	import { Injectable, OnModuleDestroy } from '@nestjs/common';
2	import { randomUUID } from 'crypto';
3	
4	/**
5	 * Lifecycle of a single post-response ("async") continuation, as observed
6	 * through `/async-records`:
7	 *
8	 * - `pending`   - the continuation has not finished yet. This covers both the
9	 *                 in-flight request (the response may still be streaming) and
10	 *                 the window after the response terminated while the
11	 *                 continuation is parked behind its gate.
12	 * - `completed` - the continuation ran and read the frozen snapshot.
13	 * - `failed`    - the continuation threw; the error message was captured and
14	 *                 only this record is affected.
15	 */
16	export type ContinuationStatus = 'pending' | 'completed' | 'failed';
17	
18	export interface ContinuationRecord {
19	  recordId: string;
20	  contextId: string;
21	  appId: string;
22	  marker: string;
23	  consumerValue: string | null;
24	  frozenMarker: string | null;
25	  status: ContinuationStatus;
26	  terminationReason: 'finish' | 'abort' | null;
27	  terminationCount: number | null;
28	  lateWriteAccepted: boolean | null;
29	  lateWriteVisible: boolean | null;
30	  readsStable: boolean | null;
31	  errorMessage: string | null;
32	  registeredAt: number;
33	}
34	
35	interface Gate {
36	  promise: Promise<void>;
37	  release: () => void;
38	}
39	
40	function createGate(): Gate {
41	  let release: () => void = () => {};
42	  const promise = new Promise<void>(resolve => {
43	    release = resolve;
44	  });
45	  return { promise, release };
46	}
47	
48	/**
49	 * Application-scoped, in-memory store of continuation records.
50	 *
51	 * Every bootstrapped Nest application builds its own instance (identified by
52	 * `appId`), so records can never leak between concurrently running
53	 * applications or be replayed after an application is recreated. The store is
54	 * a plain singleton provider: it has no dependency on the request-context
55	 * module and the control application uses an analogous, always-empty store.
56	 */
57	@Injectable()
58	export class AsyncRecordsStore implements OnModuleDestroy {
59	  public readonly appId = randomUUID();
60	
61	  private readonly records = new Map<string, ContinuationRecord>();
62	  private readonly order: string[] = [];
63	  private readonly gates = new Map<string, Gate>();
64	
65	  public register(
66	    contextId: string,
67	    recordId: string,
68	    marker: string,
69	  ): ContinuationRecord {
70	    const record: ContinuationRecord = {
71	      recordId,
72	      contextId,
73	      appId: this.appId,
74	      marker,
75	      consumerValue: null,
76	      frozenMarker: null,
77	      status: 'pending',
78	      terminationReason: null,
79	      terminationCount: null,
80	      lateWriteAccepted: null,
81	      lateWriteVisible: null,
82	      readsStable: null,
83	      errorMessage: null,
84	      // Tie-break so insertion ordering is total even within one tick.
85	      registeredAt: Date.now() + this.order.length / 1000,
86	    };
87	    this.records.set(recordId, record);
88	    this.order.push(recordId);
89	    this.gates.set(recordId, createGate());
90	    return record;
91	  }
92	
93	  public markCompleted(
94	    recordId: string,
95	    payload: Pick<
96	      ContinuationRecord,
97	      | 'consumerValue'
98	      | 'frozenMarker'
99	      | 'terminationReason'
100	      | 'terminationCount'
101	      | 'lateWriteAccepted'
102	      | 'lateWriteVisible'
103	      | 'readsStable'
104	    >,
105	  ): void {
106	    const record = this.records.get(recordId);
107	    if (!record || record.status !== 'pending') {
108	      // A settled record is immutable: late settlements can never rewrite it.
109	      return;
110	    }
111	    Object.assign(record, payload, { status: 'completed' as const });
112	  }
113	
114	  public markFailed(recordId: string, error: unknown): void {
115	    const record = this.records.get(recordId);
116	    if (!record || record.status !== 'pending') {
117	      return;
118	    }
119	    record.status = 'failed';
120	    record.errorMessage =
121	      error instanceof Error ? error.message : String(error);
122	  }
123	
124	  public waitForGate(recordId: string): Promise<void> {
125	    return this.gates.get(recordId)?.promise ?? Promise.resolve();
126	  }
127	
128	  public releaseGate(recordId: string): void {
129	    this.gates.get(recordId)?.release();
130	  }
131	
132	  public releaseAllGates(): void {
133	    this.gates.forEach(gate => gate.release());
134	  }
135	
136	  /**
137	   * Safety net for shutdown: never let a parked gate delay application close.
138	   * Runs before the HTTP adapter is disposed, so the request-context shutdown
139	   * drain that follows can await the now-unblocked continuations.
140	   */
141	  public onModuleDestroy(): void {
142	    this.releaseAllGates();
143	  }
144	
145	  public getAll(): ContinuationRecord[] {
146	    return this.order.map(id => this.records.get(id)!);
147	  }
148	}

